tool_and_message_events.command:
/bin/bash -lc "node --input-type=commonjs <<'NODE'
const ts = require('./node_modules/typescript');
const config = ts.readConfigFile('tsconfig.json', ts.sys.readFile);
const parsed = ts.parseJsonConfigFileContent(config.config, ts.sys, '.');
const program = ts.createProgram(parsed.fileNames, parsed.options);
const checker = program.getTypeChecker();
for (const statement of program.getSourceFile('src/settings.ts').statements) {
  if ("'!ts.isVariableStatement(statement)) continue;
  for (const declaration of statement.declarationList.declarations) {
    const inferred = checker.typeToString(checker.getTypeAtLocation(declaration.initializer));
    const declared = checker.typeToString(checker.getTypeAtLocation(declaration.name));
    console.log(`${declaration.name.getText()}: initializer ${inferred}; variable ${declared}`);
  }
}
NODE'
